180   *      Decode a TACACS+ field.
   181   */
   182  static int tacacs_decode_field(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_attr_t const *da,
   183                                  uint8_t const **field_data, uint16_t field_len, uint8_t const *end)
   184  {
   185          uint8_t const *p = *field_data;
   186          fr_pair_t *vp;
   187
   188          if ((p + field_len) > end) {
   189                  fr_strerror_printf("'%s' length %u overflows the remaining data in the packet",
   190                                     da->name, field_len);
   191                  return -1;
   192          }
   193
   194          vp = fr_pair_afrom_da(ctx, da);
   195          if (!vp) {
   196                  fr_strerror_const("Out of Memory");
   197                  return -1;
   198          }
   199
   200          if (field_len) {
   201                  if (da->type == FR_TYPE_STRING) {
   202                          fr_pair_value_bstrndup(vp, (char const *)p, field_len, true);
   203                  } else if (da->type == FR_TYPE_OCTETS) {
   204                          fr_pair_value_memdup(vp, p, field_len, true);
   205                  } else {
   206                          fr_assert(0);
   207                  }
   208                  p += field_len;
   209                  *field_data = p;
   210          }
   211
   212          fr_dcursor_append(cursor, vp);
   213
   214          return 0;
   215  }
